  List<ResolveInfo> installed=a.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);installed.sort((x,y)->{String xl=x.loadLabel(a.getPackageManager()).toString(),yl=y.loadLabel(a.getPackageManager()).toString();boolean xr=PaymentCards.recommended(xl,x.activityInfo.packageName),yr=PaymentCards.recommended(yl,y.activityInfo.packageName);return xr==yr?xl.compareToIgnoreCase(yl):xr?-1:1;});
  for(ResolveInfo r:installed){String p=r.activityInfo.packageName,label=r.loadLabel(a.getPackageManager()).toString();if(!p.equals(a.getPackageName())&&!all.containsKey(p))all.put(p,new JSONObject().put("package",p).put("label",label).put("kind",PaymentCards.kind(label,p)).put("account","").put("enabled",true));}
  LinearLayout box=NativeSettings.panel(a,"Apps de tus compras");box.addView(Glass.text(a,"Bancos, Wallet, Onepay y Gmail pueden escuchar a la vez.",14,false));Dialog dialog=new Dialog(a);Glass.privacy(dialog.getWindow(),a);dialog.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);EditText search=NativeSettings.input(a,box,"Buscar app","");LinearLayout choices=Modern.column(a);ScrollView listScroll=new ScrollView(a);listScroll.addView(choices);box.addView(listScroll,new LinearLayout.LayoutParams(-1,0,1));LinkedHashMap<CheckBox,JSONObject> rows=new LinkedHashMap<>();
  for(JSONObject s:all.values()){CheckBox cb=new CheckBox(a);Controls.style(cb);cb.setText(s.optString("label")+(PaymentCards.recommended(s.optString("label"),s.optString("package"))?" · Sugerida":""));cb.setMinHeight(a.dp(56));try{android.graphics.drawable.Drawable icon=a.getPackageManager().getApplicationIcon(s.optString("package"));icon.setBounds(0,0,a.dp(28),a.dp(28));cb.setCompoundDrawables(null,null,icon,null);cb.setCompoundDrawablePadding(a.dp(10));}catch(Exception ignored){}cb.setChecked(selected.contains(s.optString("package")));choices.addView(cb);rows.put(cb,s);}
  Button suggested=Glass.button(a,"Marcar apps sugeridas");box.addView(suggested,2);suggested.setOnClickListener(v->{for(Map.Entry<CheckBox,JSONObject> e:rows.entrySet())if(PaymentCards.recommended(e.getValue().optString("label"),e.getValue().optString("package")))e.getKey().setChecked(true);});
